/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountCollectionLayoutMorph, type CollectionLayoutMorphOptions } from "../../components/collection-layout-morph/CollectionLayoutMorphEngine.js";
import type { MotionController } from "../../components/collection-layout-morph/motion-runtime";

export function CollectionLayoutMorph({ options, className }: { options?: CollectionLayoutMorphOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountCollectionLayoutMorph(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="collection-layout-morph" />;
}

